<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iParamsHTTP { } class ParamsHTTP implements iParamsHTTP { public $url; public $method = 'httpGET'; public $token; public $content = Exchange::RT_APPLICATION_JSON_FHIR; public $timeout = Exchange::HTTP_TIMEOUT_DEF; public $request_content; public $param; public $proxy; public $headers; public $accept; public function cleanParams(): void { unset($this->codepage); unset($this->content); unset($this->method); unset($this->token); unset($this->accept); } public function setHeader(string $header, string $value): void { $this->headers[$header] = $value; } public function setProxy(LinkSetup $ls): void { $ls->getParam('userProxy') && $this->proxy = $ls->getParams([ 'proxyHost', 'proxyPort', 'proxyUser', 'proxyPass' ]); } public function setRequestForm(array $request_form): void { $this->request_content = http_build_query($request_form); } public function setRequestParam(array $request_param): void { $this->param = $request_param; } public function setRequestContent($request_content): void { $this->request_content = $request_content; } } 